/// Carbon / HIToolbox virtual keycodes on macOS.
const KVK_ANSI_V: u16 = 0x09;
const KVK_RETURN: u16 = 0x24;
const KVK_TAB: u16 = 0x30;

/// Pasteboard.org markers honored by Clipo, Raycast, Maccy, Paste, Alfred, and 1Password.
const PASTEBOARD_UTF8_TYPE: &str = "public.utf8-plain-text";
const PASTEBOARD_CONCEALED_TYPE: &str = "org.nspasteboard.ConcealedType";
const PASTEBOARD_TRANSIENT_TYPE: &str = "org.nspasteboard.TransientType";
const PASTEBOARD_AUTOGENERATED_TYPE: &str = "org.nspasteboard.AutoGeneratedType";

