/// Screen-space bounds, Accessibility metadata, and enclosing `AXWebArea` URL of the focused input.
#[derive(Debug, Clone, PartialEq)]
pub struct FocusedFieldBounds {
    pub pid: i32,
    pub role: String,
    pub subrole: Option<String>,
    pub title: Option<String>,
    pub description: Option<String>,
    pub placeholder: Option<String>,
    pub web_url: Option<String>,
    pub is_secure: bool,
    pub x: f64,
    pub y: f64,
    pub width: f64,
    pub height: f64,
}

#[derive(Debug, PartialEq, Eq)]
enum TypingSegment {
    Text(Vec<u16>),
    VirtualKey(u16),
}

fn split_typing_segments(input: &[u16]) -> Vec<TypingSegment> {
    let mut segments = Vec::new();
    let mut current = Vec::new();
    let mut idx = 0;

    while idx < input.len() {
        match input[idx] {
            0x0009 => {
                if !current.is_empty() {
                    segments.push(TypingSegment::Text(std::mem::take(&mut current)));
                }
                segments.push(TypingSegment::VirtualKey(KVK_TAB));
                idx += 1;
            }
            0x000D => {
                if !current.is_empty() {
                    segments.push(TypingSegment::Text(std::mem::take(&mut current)));
                }
                segments.push(TypingSegment::VirtualKey(KVK_RETURN));
                if idx + 1 < input.len() && input[idx + 1] == 0x000A {
                    idx += 2;
                } else {
                    idx += 1;
                }
            }
            0x000A => {
                if !current.is_empty() {
                    segments.push(TypingSegment::Text(std::mem::take(&mut current)));
                }
                segments.push(TypingSegment::VirtualKey(KVK_RETURN));
                idx += 1;
            }
            unit => {
                current.push(unit);
                idx += 1;
            }
        }
    }

    if !current.is_empty() {
        segments.push(TypingSegment::Text(current));
    }

    segments
}

