unsafe fn make_cf_string(text: &str) -> CFStringRef {
    unsafe {
        CFStringCreateWithBytes(
            std::ptr::null(),
            text.as_ptr(),
            text.len() as isize,
            KCF_STRING_ENCODING_UTF8,
            false,
        )
    }
}

unsafe fn cf_string_to_rust(cf_str: CFStringRef) -> Option<String> {
    if cf_str.is_null() {
        return None;
    }
    unsafe {
        let len = CFStringGetLength(cf_str);
        let max_bytes = CFStringGetMaximumSizeForEncoding(len, KCF_STRING_ENCODING_UTF8) + 1;
        if max_bytes <= 0 {
            return Some(String::new());
        }
        let mut buf = vec![0u8; max_bytes as usize];
        if !CFStringGetCString(
            cf_str,
            buf.as_mut_ptr(),
            max_bytes,
            KCF_STRING_ENCODING_UTF8,
        ) {
            return None;
        }
        let nul = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
        buf.truncate(nul);
        String::from_utf8(buf).ok()
    }
}

unsafe fn cf_url_or_string_to_rust(value: CFTypeRef) -> Option<String> {
    if value.is_null() {
        return None;
    }
    unsafe {
        let type_id = CFGetTypeID(value);
        if type_id == CFStringGetTypeID() {
            return cf_string_to_rust(value).filter(|s| !s.is_empty());
        }
        if type_id == CFURLGetTypeID() {
            let url_str = CFURLGetString(value);
            return cf_string_to_rust(url_str).filter(|s| !s.is_empty());
        }
        None
    }
}

unsafe fn copy_ax_attr(element: AXUIElementRef, name: &str) -> CFTypeRef {
    if element.is_null() {
        return std::ptr::null();
    }
    unsafe {
        let attr = make_cf_string(name);
        if attr.is_null() {
            return std::ptr::null();
        }
        let mut out: CFTypeRef = std::ptr::null();
        let status = AXUIElementCopyAttributeValue(element, attr, &mut out);
        CFRelease(attr);
        if status == 0 {
            out
        } else {
            std::ptr::null()
        }
    }
}

unsafe fn copy_ax_string(element: AXUIElementRef, name: &str) -> Option<String> {
    unsafe {
        let raw = copy_ax_attr(element, name);
        if raw.is_null() {
            return None;
        }
        let text = cf_url_or_string_to_rust(raw);
        CFRelease(raw);
        text
    }
}

/// Walks `AXParent` ancestors from `element` to locate an enclosing `AXWebArea` or window URL.
unsafe fn find_web_url_from_ancestors(element: AXUIElementRef) -> Option<String> {
    if element.is_null() {
        return None;
    }
    unsafe {
        let mut current: AXUIElementRef = element;
        let mut owned_current = false;
        let mut depth = 0;

        while !current.is_null() && depth < 36 {
            if let Some(url) = copy_ax_string(current, "AXURL")
                .or_else(|| copy_ax_string(current, "AXDocument"))
                .filter(|u| {
                    u.starts_with("https://")
                        || u.starts_with("http://")
                        || u.starts_with("file://")
                })
            {
                if owned_current {
                    CFRelease(current);
                }
                return Some(url);
            }

            let next = copy_ax_attr(current, "AXParent");
            if owned_current {
                CFRelease(current);
            }
            current = next;
            owned_current = true;
            depth += 1;
        }

        if owned_current && !current.is_null() {
            CFRelease(current);
        }
        None
    }
}

/// Breadth-first scan of the focused window's AX tree (bounded to 96 elements) to read `AXWebArea`
/// `AXURL` / `AXDocument` without triggering macOS AppleScript Automation popups.
unsafe fn find_web_url_in_focused_window(app_elem: AXUIElementRef) -> Option<String> {
    if app_elem.is_null() {
        return None;
    }
    unsafe {
        let win = {
            let focused_win = copy_ax_attr(app_elem, "AXFocusedWindow");
            if !focused_win.is_null() {
                focused_win
            } else {
                copy_ax_attr(app_elem, "AXMainWindow")
            }
        };
        if win.is_null() {
            return None;
        }

        if let Some(doc_url) = copy_ax_string(win, "AXURL")
            .or_else(|| copy_ax_string(win, "AXDocument"))
            .filter(|u| {
                u.starts_with("https://") || u.starts_with("http://") || u.starts_with("file://")
            })
        {
            CFRelease(win);
            return Some(doc_url);
        }

        let mut queue: VecDeque<AXUIElementRef> = VecDeque::new();
        queue.push_back(win);
        let mut visited = 0usize;
        let mut found: Option<String> = None;

        while let Some(node) = queue.pop_front() {
            visited += 1;
            if found.is_none() {
                let role = copy_ax_string(node, "AXRole").unwrap_or_default();
                if role == "AXWebArea" {
                    found = copy_ax_string(node, "AXURL")
                        .or_else(|| copy_ax_string(node, "AXDocument"))
                        .filter(|u| {
                            u.starts_with("https://")
                                || u.starts_with("http://")
                                || u.starts_with("file://")
                        });
                }
            }

            if found.is_none() && visited < 96 {
                let children = copy_ax_attr(node, "AXChildren");
                if !children.is_null() {
                    if CFGetTypeID(children) == CFArrayGetTypeID() {
                        let count = CFArrayGetCount(children).min(24);
                        for idx in 0..count {
                            let child = CFArrayGetValueAtIndex(children, idx);
                            if !child.is_null() {
                                CFRetain(child);
                                queue.push_back(child);
                            }
                        }
                    }
                    CFRelease(children);
                }
            }

            CFRelease(node);
            if found.is_some() {
                break;
            }
        }

        for remaining in queue {
            if !remaining.is_null() {
                CFRelease(remaining);
            }
        }
        found
    }
}

extern "C" {
    fn CFRetain(cf: CFTypeRef) -> CFTypeRef;
    fn CFArrayGetTypeID() -> usize;
}

/// Finds the frontmost standard (`kCGWindowLayer == 0`) window's owner PID and window title.
fn frontmost_window_pid_and_title() -> Option<(i32, String)> {
    unsafe {
        let list = CGWindowListCopyWindowInfo(
            KCG_WINDOW_LIST_OPTION_ON_SCREEN_ONLY | KCG_WINDOW_LIST_EXCLUDE_DESKTOP_ELEMENTS,
            0,
        );
        if list.is_null() {
            return None;
        }
        let key_layer = make_cf_string("kCGWindowLayer");
        let key_pid = make_cf_string("kCGWindowOwnerPID");
        let key_name = make_cf_string("kCGWindowName");
        let key_owner = make_cf_string("kCGWindowOwnerName");

        let count = CFArrayGetCount(list);
        let mut found = None;
        for idx in 0..count {
            let dict = CFArrayGetValueAtIndex(list, idx);
            if dict.is_null() {
                continue;
            }
            let layer_ref = CFDictionaryGetValue(dict, key_layer);
            let mut layer: i32 = -1;
            if layer_ref.is_null()
                || !CFNumberGetValue(
                    layer_ref,
                    KCF_NUMBER_SINT32_TYPE,
                    (&mut layer as *mut i32).cast(),
                )
                || layer != 0
            {
                continue;
            }
            let pid_ref = CFDictionaryGetValue(dict, key_pid);
            let mut pid: i32 = 0;
            if pid_ref.is_null()
                || !CFNumberGetValue(
                    pid_ref,
                    KCF_NUMBER_SINT32_TYPE,
                    (&mut pid as *mut i32).cast(),
                )
                || pid <= 0
            {
                continue;
            }
            let title_ref = CFDictionaryGetValue(dict, key_name);
            let owner_ref = CFDictionaryGetValue(dict, key_owner);
            let title = cf_string_to_rust(title_ref)
                .filter(|s| !s.is_empty())
                .or_else(|| cf_string_to_rust(owner_ref))
                .unwrap_or_default();
            found = Some((pid, title));
            break;
        }

        for k in [key_layer, key_pid, key_name, key_owner] {
            if !k.is_null() {
                CFRelease(k);
            }
        }
        CFRelease(list);
        found
    }
}

/// Enables Chromium (`Google Chrome`, `Brave`, `Arc`, `Edge`, `Vivaldi`), Safari, and Electron AX
/// trees on macOS (`AXManualAccessibility` + `AXEnhancedUserInterface`) — the same mechanism used
/// by ChatGPT.app ("Work with Apps") and Raycast.app to expose `AXWebArea` URLs and input bounds.
pub fn enable_manual_accessibility(pid: i32) {
    if pid <= 0 {
        return;
    }
    unsafe {
        let app_elem = AXUIElementCreateApplication(pid);
        if app_elem.is_null() {
            return;
        }
        let manual_attr = make_cf_string("AXManualAccessibility");
        let enhanced_attr = make_cf_string("AXEnhancedUserInterface");
        if !manual_attr.is_null() {
            let _ = AXUIElementSetAttributeValue(app_elem, manual_attr, kCFBooleanTrue);
            CFRelease(manual_attr);
        }
        if !enhanced_attr.is_null() {
            let _ = AXUIElementSetAttributeValue(app_elem, enhanced_attr, kCFBooleanTrue);
            CFRelease(enhanced_attr);
        }
        CFRelease(app_elem);
    }
}

/// Reads the active browser tab or document URL (`AXURL` / `AXDocument` on `AXWebArea` or the
/// focused window) without AppleScript Automation prompts.
pub fn inspect_frontmost_web_url() -> Option<String> {
    let (pid, _) = frontmost_window_pid_and_title()?;
    enable_manual_accessibility(pid);
    unsafe {
        let app_elem = AXUIElementCreateApplication(pid);
        if app_elem.is_null() {
            return None;
        }
        let focused = copy_ax_attr(app_elem, "AXFocusedUIElement");
        let mut url = if !focused.is_null() {
            let from_ancestors = find_web_url_from_ancestors(focused);
            CFRelease(focused);
            from_ancestors
        } else {
            None
        };
        if url.is_none() {
            url = find_web_url_in_focused_window(app_elem);
        }
        CFRelease(app_elem);
        url
    }
}

/// Inspects the focused `<input>` / text control in the frontmost application after enabling
/// `AXManualAccessibility` and `AXEnhancedUserInterface`, returning screen bounds, labels,
/// `AXSecureTextField` status, and enclosing `AXWebArea` URL.
pub fn inspect_focused_input_field() -> Option<FocusedFieldBounds> {
    let (pid, _) = frontmost_window_pid_and_title()?;
    enable_manual_accessibility(pid);

    unsafe {
        let app_elem = AXUIElementCreateApplication(pid);
        if app_elem.is_null() {
            return None;
        }
        let focused = copy_ax_attr(app_elem, "AXFocusedUIElement");
        if focused.is_null() {
            CFRelease(app_elem);
            return None;
        }

        let role = copy_ax_string(focused, "AXRole").unwrap_or_default();
        let subrole = copy_ax_string(focused, "AXSubrole");
        let title = copy_ax_string(focused, "AXTitle");
        let description = copy_ax_string(focused, "AXDescription");
        let placeholder = copy_ax_string(focused, "AXPlaceholderValue");
        let web_url = find_web_url_from_ancestors(focused)
            .or_else(|| find_web_url_in_focused_window(app_elem));

        let pos_ref = copy_ax_attr(focused, "AXPosition");
        let size_ref = copy_ax_attr(focused, "AXSize");

        let mut point = CGPoint::default();
        let mut size = CGSize::default();
        let has_pos = !pos_ref.is_null()
            && AXValueGetValue(
                pos_ref,
                KAX_VALUE_CGPOINT_TYPE,
                (&mut point as *mut CGPoint).cast(),
            );
        let has_size = !size_ref.is_null()
            && AXValueGetValue(
                size_ref,
                KAX_VALUE_CGSIZE_TYPE,
                (&mut size as *mut CGSize).cast(),
            );

        for val in [pos_ref, size_ref, focused, app_elem] {
            if !val.is_null() {
                CFRelease(val);
            }
        }

        let is_text_input = matches!(
            role.as_str(),
            "AXTextField" | "AXTextArea" | "AXComboBox" | "AXSearchField"
        );
        if !is_text_input || !has_pos || !has_size || size.width <= 0.0 || size.height <= 0.0 {
            return None;
        }

        let is_secure = subrole.as_deref() == Some("AXSecureTextField");

        Some(FocusedFieldBounds {
            pid,
            role,
            subrole,
            title,
            description,
            placeholder,
            web_url,
            is_secure,
            x: point.x,
            y: point.y,
            width: size.width,
            height: size.height,
        })
    }
}

fn chromium_user_data_dir(bundle_id: &str) -> Option<PathBuf> {
    let home = std::env::var_os("HOME").map(PathBuf::from)?;
    let app_support = home.join("Library").join("Application Support");
    match bundle_id {
        "com.google.Chrome" => Some(app_support.join("Google").join("Chrome")),
        "com.google.Chrome.canary" => Some(app_support.join("Google").join("Chrome Canary")),
        "com.brave.Browser" => Some(app_support.join("BraveSoftware").join("Brave-Browser")),
        "com.microsoft.edgemac" => Some(app_support.join("Microsoft Edge")),
        "company.thebrowser.Browser" => Some(app_support.join("Arc").join("User Data")),
        "com.vivaldi.Vivaldi" => Some(app_support.join("Vivaldi")),
        "org.chromium.Chromium" => Some(app_support.join("Chromium")),
        _ => None,
    }
}

/// Checks Chromium `Local State` + active profile `Preferences` / `Secure Preferences` so the
/// desktop floating field pill does not double-render on top of Vowkey's own browser extension pill.
pub fn has_vowkey_chromium_extension(bundle_id: &str) -> bool {
    let Some(user_data_dir) = chromium_user_data_dir(bundle_id) else {
        return false;
    };
    has_vowkey_extension_in_user_data_dir(&user_data_dir)
}

fn has_vowkey_extension_in_user_data_dir(user_data_dir: &std::path::Path) -> bool {
    if !user_data_dir.exists() {
        return false;
    }

    let mut candidate_profiles = vec![String::from("Default")];
    if let Ok(local_state) = fs::read_to_string(user_data_dir.join("Local State")) {
        if let Some(last_used) = extract_json_string_after(&local_state, "\"last_used\"") {
            if !last_used.is_empty() && !candidate_profiles.contains(&last_used) {
                candidate_profiles.insert(0, last_used);
            }
        }
    }

    for profile in candidate_profiles {
        let profile_dir = user_data_dir.join(&profile);
        for file_name in ["Preferences", "Secure Preferences"] {
            if let Ok(contents) = fs::read_to_string(profile_dir.join(file_name)) {
                let lower = contents.to_ascii_lowercase();
                if (lower.contains("vowkey") || lower.contains("com.vowkey.app"))
                    && lower.contains("\"state\":1")
                {
                    return true;
                }
            }
        }
    }

    false
}

fn extract_json_string_after(haystack: &str, key: &str) -> Option<String> {
    let idx = haystack.find(key)?;
    let rest = haystack.get(idx + key.len()..)?;
    let colon_idx = rest.find(':')?;
    let after_colon = rest.get(colon_idx + 1..)?.trim_start();
    let inner = after_colon.strip_prefix('"')?;
    let mut out = String::new();
    let mut escaped = false;
    for ch in inner.chars() {
        if escaped {
            out.push(ch);
            escaped = false;
        } else if ch == '\\' {
            escaped = true;
        } else if ch == '"' {
            return Some(out);
        } else {
            out.push(ch);
        }
    }
    None
}

