unsafe fn general_pasteboard() -> ObjCId {
    unsafe {
        let pb_cls = cls(b"NSPasteboard\0");
        if pb_cls.is_null() {
            return std::ptr::null_mut();
        }
        let msg: unsafe extern "C" fn(ObjCClass, ObjCSel) -> ObjCId =
            std::mem::transmute(objc_msgSend as *const ());
        msg(pb_cls, sel(b"generalPasteboard\0"))
    }
}

unsafe fn pasteboard_change_count(pb: ObjCId) -> isize {
    if pb.is_null() {
        return 0;
    }
    unsafe {
        let msg: unsafe extern "C" fn(ObjCId, ObjCSel) -> isize =
            std::mem::transmute(objc_msgSend as *const ());
        msg(pb, sel(b"changeCount\0"))
    }
}

unsafe fn snapshot_pasteboard(pb: ObjCId) -> PasteboardSnapshot {
    if pb.is_null() {
        return Vec::new();
    }
    unsafe {
        let msg_items: unsafe extern "C" fn(ObjCId, ObjCSel) -> CFArrayRef =
            std::mem::transmute(objc_msgSend as *const ());
        let msg_types: unsafe extern "C" fn(ObjCId, ObjCSel) -> CFArrayRef =
            std::mem::transmute(objc_msgSend as *const ());
        let msg_data: unsafe extern "C" fn(ObjCId, ObjCSel, CFStringRef) -> CFDataRef =
            std::mem::transmute(objc_msgSend as *const ());

        let items = msg_items(pb, sel(b"pasteboardItems\0"));
        if items.is_null() {
            return Vec::new();
        }
        let item_count = CFArrayGetCount(items);
        let mut snapshot = Vec::with_capacity(item_count.max(0) as usize);

        for i in 0..item_count {
            let item = CFArrayGetValueAtIndex(items, i) as ObjCId;
            if item.is_null() {
                continue;
            }
            let types = msg_types(item, sel(b"types\0"));
            if types.is_null() {
                continue;
            }
            let type_count = CFArrayGetCount(types);
            let mut entries = Vec::with_capacity(type_count.max(0) as usize);
            for t_idx in 0..type_count {
                let ut_ref = CFArrayGetValueAtIndex(types, t_idx);
                let Some(ut_name) = cf_string_to_rust(ut_ref) else {
                    continue;
                };
                // Skip restoring previously concealed/transient items.
                if ut_name == PASTEBOARD_CONCEALED_TYPE || ut_name == PASTEBOARD_TRANSIENT_TYPE {
                    entries.clear();
                    break;
                }
                let data_ref = msg_data(item, sel(b"dataForType:\0"), ut_ref);
                if data_ref.is_null() {
                    continue;
                }
                let len = CFDataGetLength(data_ref);
                let bytes = if len > 0 {
                    let ptr = CFDataGetBytePtr(data_ref);
                    if ptr.is_null() {
                        Vec::new()
                    } else {
                        std::slice::from_raw_parts(ptr, len as usize).to_vec()
                    }
                } else {
                    Vec::new()
                };
                entries.push((ut_name, bytes));
            }
            if !entries.is_empty() {
                snapshot.push(entries);
            }
        }
        snapshot
    }
}

/// Writes `text` to `pb` along with empty data markers for `ConcealedType`, `TransientType`, and
/// `AutoGeneratedType` (matching Raycast's `NSPasteboard+Additions.swift`), returning `changeCount`.
unsafe fn write_concealed_pasteboard(pb: ObjCId, text: &str) -> isize {
    if pb.is_null() {
        return 0;
    }
    unsafe {
        let msg_clear: unsafe extern "C" fn(ObjCId, ObjCSel) -> isize =
            std::mem::transmute(objc_msgSend as *const ());
        let msg_set_str: unsafe extern "C" fn(ObjCId, ObjCSel, CFStringRef, CFStringRef) -> bool =
            std::mem::transmute(objc_msgSend as *const ());
        let msg_set_data: unsafe extern "C" fn(ObjCId, ObjCSel, CFDataRef, CFStringRef) -> bool =
            std::mem::transmute(objc_msgSend as *const ());

        let _ = msg_clear(pb, sel(b"clearContents\0"));

        let cf_text = make_cf_string(text);
        let cf_utf8 = make_cf_string(PASTEBOARD_UTF8_TYPE);
        if !cf_text.is_null() && !cf_utf8.is_null() {
            let _ = msg_set_str(pb, sel(b"setString:forType:\0"), cf_text, cf_utf8);
        }
        if !cf_text.is_null() {
            CFRelease(cf_text);
        }
        if !cf_utf8.is_null() {
            CFRelease(cf_utf8);
        }

        let empty_data = CFDataCreate(std::ptr::null(), std::ptr::null(), 0);
        if !empty_data.is_null() {
            for marker in [
                PASTEBOARD_CONCEALED_TYPE,
                PASTEBOARD_TRANSIENT_TYPE,
                PASTEBOARD_AUTOGENERATED_TYPE,
            ] {
                let cf_marker = make_cf_string(marker);
                if !cf_marker.is_null() {
                    let _ = msg_set_data(pb, sel(b"setData:forType:\0"), empty_data, cf_marker);
                    CFRelease(cf_marker);
                }
            }
            CFRelease(empty_data);
        }

        pasteboard_change_count(pb)
    }
}

unsafe fn restore_pasteboard_if_unchanged(
    pb: ObjCId,
    snapshot: &PasteboardSnapshot,
    expected_change_count: isize,
) {
    if pb.is_null() {
        return;
    }
    unsafe {
        if pasteboard_change_count(pb) != expected_change_count {
            return;
        }
        let msg_clear: unsafe extern "C" fn(ObjCId, ObjCSel) -> isize =
            std::mem::transmute(objc_msgSend as *const ());
        let _ = msg_clear(pb, sel(b"clearContents\0"));

        if snapshot.is_empty() {
            return;
        }

        let item_cls = cls(b"NSPasteboardItem\0");
        if item_cls.is_null() {
            return;
        }
        let msg_alloc: unsafe extern "C" fn(ObjCClass, ObjCSel) -> ObjCId =
            std::mem::transmute(objc_msgSend as *const ());
        let msg_init: unsafe extern "C" fn(ObjCId, ObjCSel) -> ObjCId =
            std::mem::transmute(objc_msgSend as *const ());
        let msg_set_data: unsafe extern "C" fn(ObjCId, ObjCSel, CFDataRef, CFStringRef) -> bool =
            std::mem::transmute(objc_msgSend as *const ());
        let msg_write_objs: unsafe extern "C" fn(ObjCId, ObjCSel, CFArrayRef) -> bool =
            std::mem::transmute(objc_msgSend as *const ());

        let array = CFArrayCreateMutable(
            std::ptr::null(),
            snapshot.len() as isize,
            &kCFTypeArrayCallBacks,
        );
        if array.is_null() {
            return;
        }

        for item_entries in snapshot {
            let raw_item = msg_alloc(item_cls, sel(b"alloc\0"));
            if raw_item.is_null() {
                continue;
            }
            let item = msg_init(raw_item, sel(b"init\0"));
            if item.is_null() {
                continue;
            }
            for (ut_type, bytes) in item_entries {
                let cf_type = make_cf_string(ut_type);
                let cf_data = CFDataCreate(
                    std::ptr::null(),
                    if bytes.is_empty() {
                        std::ptr::null()
                    } else {
                        bytes.as_ptr()
                    },
                    bytes.len() as isize,
                );
                if !cf_type.is_null() && !cf_data.is_null() {
                    let _ = msg_set_data(item, sel(b"setData:forType:\0"), cf_data, cf_type);
                }
                if !cf_type.is_null() {
                    CFRelease(cf_type);
                }
                if !cf_data.is_null() {
                    CFRelease(cf_data);
                }
            }
            CFArrayAppendValue(array, item.cast());
            CFRelease(item.cast());
        }

        let _ = msg_write_objs(pb, sel(b"writeObjects:\0"), array.cast());
        CFRelease(array.cast());
    }
}

/// Whether Vowkey may post keyboard events; asks macOS to show its prompt when it may not.
fn accessibility_allowed() -> bool {
    // SAFETY: the dictionary holds two constant CoreFoundation objects and is released below.
    unsafe {
        let keys = [kAXTrustedCheckOptionPrompt];
        let values = [kCFBooleanTrue];
        let options = CFDictionaryCreate(
            std::ptr::null(),
            keys.as_ptr(),
            values.as_ptr(),
            1,
            &kCFTypeDictionaryKeyCallBacks,
            &kCFTypeDictionaryValueCallBacks,
        );
        let allowed = AXIsProcessTrustedWithOptions(options);
        if !options.is_null() {
            CFRelease(options);
        }
        allowed
    }
}

/// Returns the foreground window title and enables `AXManualAccessibility` + `AXEnhancedUserInterface`
/// on the frontmost app so Chromium and Safari expose `AXWebArea` and focused `<input>` bounds.
pub fn get_foreground_window_title() -> Result<String> {
    if let Some((pid, title)) = frontmost_window_pid_and_title() {
        enable_manual_accessibility(pid);
        return Ok(title);
    }
    Ok(String::new())
}

unsafe fn post_virtual_key(source: CGEventSourceRef, keycode: u16, flags: u64) -> Result<()> {
    unsafe {
        for down in [true, false] {
            let event = CGEventCreateKeyboardEvent(source, keycode, down);
            if event.is_null() {
                return Err(anyhow!("macOS did not create a keyboard event."));
            }
            CGEventSetFlags(event, flags);
            CGEventPost(KCG_HID_EVENT_TAP, event);
            CFRelease(event as CFTypeRef);
        }
    }
    Ok(())
}

/// Fills `input` (UTF-16) into the focused field using Raycast-style concealed transient paste
/// (`⌘V` with `ConcealedType` / `TransientType` / `AutoGeneratedType`) for text segments and clean
/// virtual keycodes (`Tab` / `Return`) for navigation, then restores the previous `NSPasteboard`
/// snapshot ~150 ms later.
pub fn type_input(input: &[u16], _keyboard_shortcut: &[String]) -> Result<()> {
    if !accessibility_allowed() {
        return Err(anyhow!(
            "Allow Vowkey under System Settings › Privacy & Security › Accessibility to type into other apps."
        ));
    }
    let segments = split_typing_segments(input);
    if segments.is_empty() {
        return Ok(());
    }

    unsafe {
        let pb = general_pasteboard();
        let snapshot = snapshot_pasteboard(pb);
        let mut last_change_count: Option<isize> = None;
        let source = CGEventSourceCreate(KCG_EVENT_SOURCE_STATE_HID_SYSTEM_STATE);

        let send_result: Result<()> = (|| {
            for segment in segments {
                match segment {
                    TypingSegment::Text(units) => {
                        let text = String::from_utf16_lossy(&units);
                        if text.is_empty() {
                            continue;
                        }
                        last_change_count = Some(write_concealed_pasteboard(pb, &text));
                        post_virtual_key(source, KVK_ANSI_V, KCG_EVENT_FLAG_MASK_COMMAND)?;
                        thread::sleep(Duration::from_millis(55));
                    }
                    TypingSegment::VirtualKey(keycode) => {
                        thread::sleep(Duration::from_millis(20));
                        post_virtual_key(source, keycode, 0)?;
                        thread::sleep(Duration::from_millis(40));
                    }
                }
            }
            Ok(())
        })();

        if !source.is_null() {
            CFRelease(source as CFTypeRef);
        }

        if let Some(expected_change) = last_change_count {
            thread::spawn(move || {
                thread::sleep(Duration::from_millis(150));
                let live_pb = general_pasteboard();
                restore_pasteboard_if_unchanged(live_pb, &snapshot, expected_change);
            });
        }

        send_result
    }
}

#[cfg(test)]
mod tests {
    use super::{
        cf_string_to_rust, cls, enable_manual_accessibility, has_vowkey_extension_in_user_data_dir,
        make_cf_string, objc_msgSend, restore_pasteboard_if_unchanged, sel, snapshot_pasteboard,
        split_typing_segments, write_concealed_pasteboard, CFDataRef, CFRelease, CFStringRef,
        ObjCClass, ObjCId, ObjCSel, TypingSegment, KVK_RETURN, KVK_TAB,
        PASTEBOARD_AUTOGENERATED_TYPE, PASTEBOARD_CONCEALED_TYPE, PASTEBOARD_TRANSIENT_TYPE,
        PASTEBOARD_UTF8_TYPE,
    };

    #[test]
    fn splits_tab_between_username_and_password() {
        let utf16: Vec<u16> = "linh@example.com\ts3cr3t!".encode_utf16().collect();
        assert_eq!(
            split_typing_segments(&utf16),
            vec![
                TypingSegment::Text("linh@example.com".encode_utf16().collect()),
                TypingSegment::VirtualKey(KVK_TAB),
                TypingSegment::Text("s3cr3t!".encode_utf16().collect()),
            ]
        );
    }

    #[test]
    fn coalesces_crlf_into_single_return_keycode() {
        let utf16: Vec<u16> = "user\r\npass\n".encode_utf16().collect();
        assert_eq!(
            split_typing_segments(&utf16),
            vec![
                TypingSegment::Text("user".encode_utf16().collect()),
                TypingSegment::VirtualKey(KVK_RETURN),
                TypingSegment::Text("pass".encode_utf16().collect()),
                TypingSegment::VirtualKey(KVK_RETURN),
            ]
        );
    }

    #[test]
    fn manual_accessibility_ignores_non_positive_pid() {
        enable_manual_accessibility(0);
        enable_manual_accessibility(-1);
    }

    #[test]
    fn concealed_transient_pasteboard_roundtrips_unicode_and_restores_snapshot() {
        unsafe {
            let pb_cls = cls(b"NSPasteboard\0");
            assert!(!pb_cls.is_null());
            let msg_unique: unsafe extern "C" fn(ObjCClass, ObjCSel) -> ObjCId =
                std::mem::transmute(objc_msgSend as *const ());
            let msg_clear: unsafe extern "C" fn(ObjCId, ObjCSel) -> isize =
                std::mem::transmute(objc_msgSend as *const ());
            let msg_set_str: unsafe extern "C" fn(
                ObjCId,
                ObjCSel,
                CFStringRef,
                CFStringRef,
            ) -> bool = std::mem::transmute(objc_msgSend as *const ());
            let msg_str_for_type: unsafe extern "C" fn(
                ObjCId,
                ObjCSel,
                CFStringRef,
            ) -> CFStringRef = std::mem::transmute(objc_msgSend as *const ());
            let msg_data_for_type: unsafe extern "C" fn(ObjCId, ObjCSel, CFStringRef) -> CFDataRef =
                std::mem::transmute(objc_msgSend as *const ());
            let msg_release_globally: unsafe extern "C" fn(ObjCId, ObjCSel) =
                std::mem::transmute(objc_msgSend as *const ());

            let pb = msg_unique(pb_cls, sel(b"pasteboardWithUniqueName\0"));
            assert!(!pb.is_null());

            // 1. Seed initial user clipboard item.
            let _ = msg_clear(pb, sel(b"clearContents\0"));
            let initial_str = make_cf_string("keep-my-clipboard");
            let utf8_type = make_cf_string(PASTEBOARD_UTF8_TYPE);
            assert!(msg_set_str(
                pb,
                sel(b"setString:forType:\0"),
                initial_str,
                utf8_type
            ));
            CFRelease(initial_str);

            // 2. Snapshot and write concealed Vietnamese + Japanese text.
            let snapshot = snapshot_pasteboard(pb);
            assert_eq!(snapshot.len(), 1);
            let change_count = write_concealed_pasteboard(pb, "Nguyễn Thị Linh · 東京都港区");

            let read_back =
                cf_string_to_rust(msg_str_for_type(pb, sel(b"stringForType:\0"), utf8_type));
            assert_eq!(read_back.as_deref(), Some("Nguyễn Thị Linh · 東京都港区"));

            for marker in [
                PASTEBOARD_CONCEALED_TYPE,
                PASTEBOARD_TRANSIENT_TYPE,
                PASTEBOARD_AUTOGENERATED_TYPE,
            ] {
                let cf_marker = make_cf_string(marker);
                let marker_data = msg_data_for_type(pb, sel(b"dataForType:\0"), cf_marker);
                assert!(
                    !marker_data.is_null(),
                    "missing pasteboard privacy marker {marker}"
                );
                CFRelease(cf_marker);
            }

            // 3. Restore snapshot when changeCount matches.
            restore_pasteboard_if_unchanged(pb, &snapshot, change_count);
            let restored =
                cf_string_to_rust(msg_str_for_type(pb, sel(b"stringForType:\0"), utf8_type));
            assert_eq!(restored.as_deref(), Some("keep-my-clipboard"));

            CFRelease(utf8_type);
            msg_release_globally(pb, sel(b"releaseGlobally\0"));
        }
    }

    #[test]
    fn detects_enabled_vowkey_chromium_extension_in_profile_preferences() {
        let tmp = std::env::temp_dir().join(format!("vowkey-ext-check-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&tmp);
        let profile_dir = tmp.join("Profile 2");
        assert!(std::fs::create_dir_all(&profile_dir).is_ok());
        assert!(std::fs::write(
            tmp.join("Local State"),
            r#"{"profile":{"last_used":"Profile 2"}}"#
        )
        .is_ok());
        assert!(std::fs::write(
            profile_dir.join("Preferences"),
            r#"{"extensions":{"settings":{"abcdef":{"manifest":{"name":"Vowkey"},"state":1}}}}"#
        )
        .is_ok());

        assert!(has_vowkey_extension_in_user_data_dir(&tmp));
        let _ = std::fs::remove_dir_all(&tmp);
    }
}
